CREATE TABLE lines (
            file     TEXT,
            line_num INTEGER,
            content  TEXT,
            symbol   TEXT,
            PRIMARY KEY (file, line_num)
        );
CREATE VIRTUAL TABLE lines_fts USING fts5(file, line_num, content, symbol)
/* lines_fts(file,line_num,content,symbol) */;
CREATE TABLE 'lines_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'lines_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE 'lines_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3);
CREATE TABLE 'lines_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'lines_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE symbols (
            id             INTEGER PRIMARY KEY,
            name           TEXT,
            qualified_name TEXT,
            kind           TEXT,
            file           TEXT,
            start_line     INTEGER,
            end_line       INTEGER,
            parent         TEXT,
            signature      TEXT
        );
CREATE TABLE calls (
            caller_file   TEXT,
            caller_symbol TEXT,
            callee        TEXT,
            callee_qname  TEXT,
            kind          TEXT,
            line_num      INTEGER
        );
CREATE TABLE defs (
            symbol TEXT,
            file   TEXT,
            line_num INTEGER,
            var    TEXT,
            kind   TEXT
        );
CREATE TABLE imports (
            file   TEXT,
            module TEXT,
            line_num INTEGER
        );
CREATE TABLE blocks (
            file          TEXT,
            open_line     INTEGER,
            close_line    INTEGER,
            kind          TEXT,
            parent_symbol TEXT
        );
CREATE TABLE match_arms (
            file        TEXT,
            parent_fn   TEXT,
            pattern     TEXT,
            start_line  INTEGER,
            end_line    INTEGER,
            body_start  INTEGER,
            body_end    INTEGER,
            has_early_return INTEGER DEFAULT 0
        );
CREATE TABLE refs (
            file     TEXT,
            line_num INTEGER,
            name     TEXT,
            kind     TEXT
        );
CREATE INDEX idx_symbols_name ON symbols(name);
CREATE INDEX idx_symbols_qualified ON symbols(qualified_name);
CREATE INDEX idx_symbols_file ON symbols(file);
CREATE INDEX idx_calls_callee ON calls(callee);
CREATE INDEX idx_calls_caller ON calls(caller_symbol);
CREATE INDEX idx_defs_var ON defs(var);
CREATE INDEX idx_imports_module ON imports(module);
CREATE INDEX idx_blocks_file ON blocks(file);
CREATE INDEX idx_blocks_open ON blocks(file, open_line);
CREATE INDEX idx_match_arms_file ON match_arms(file);
CREATE INDEX idx_refs_file_line ON refs(file, line_num);
CREATE INDEX idx_refs_name ON refs(name);
CREATE TABLE files (
            file           TEXT PRIMARY KEY,
            lines          INTEGER,
            language       TEXT,
            indexed_mtime  REAL,
            indexed_size   INTEGER DEFAULT 0,
            parse_error    INTEGER DEFAULT 0
        );
CREATE TABLE directories (
            path        TEXT PRIMARY KEY,
            file_count  INTEGER,
            total_lines INTEGER
        );
